import {
    Table,
    StringColumn,
    IntegerColumn,
    GenericColumn,
    DateTimeColumn,
    ReferenceColumn,
    GuidColumn,
} from '@servicenow/sdk/core'

export const cmn_department = Table({
    actions: ['read', 'update', 'create'],
    allowClientScripts: true,
    allowNewFields: true,
    allowUiActions: true,
    allowWebServiceAccess: true,
    attributes: {
        kagami_csindex_enabled: true,
    },
    label: 'Department',
    name: 'cmn_department',
    schema: {
        id: StringColumn({
            label: 'ID',
        }),
        head_count: IntegerColumn({
            label: 'Head count',
        }),
        parent_hp1: GenericColumn({
            attributes: {
                loader_exempt: true,
                serializer: 'com.glide.script.OmittedElementXMLSerializer',
            },
            columnType: 'record_hierarchy_path',
            label: 'Parent HP1',
            maxLength: 255,
            readOnly: true,
        }),
        sys_created_on: DateTimeColumn({
            label: [
                {
                    label: 'Created',
                    plural: 'Created',
                    language: 'en',
                },
            ],
        }),
        description: StringColumn({
            label: 'Description',
            maxLength: 1000,
        }),
        sys_updated_on: DateTimeColumn({
            label: [
                {
                    label: 'Updated',
                    plural: 'Updated',
                    language: 'en',
                },
            ],
        }),
        dept_head: ReferenceColumn({
            dependent: 'company',
            label: 'Department head',
            referenceTable: 'sys_user',
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                    language: 'en',
                },
            ],
            primary: true,
        }),
        business_unit: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Business unit',
            referenceTable: 'business_unit',
        }),
        name: StringColumn({
            label: 'Name',
            maxLength: 100,
        }),
        cost_center: ReferenceColumn({
            label: 'Cost center',
            referenceTable: 'cmn_cost_center',
        }),
        sys_mod_count: IntegerColumn({
            label: [
                {
                    label: 'Updates',
                    plural: 'Updates',
                    language: 'en',
                },
            ],
        }),
        parent: ReferenceColumn({
            attributes: {
                tree_picker: true,
            },
            label: 'Parent',
            referenceTable: 'cmn_department',
        }),
        sys_created_by: StringColumn({
            label: [
                {
                    label: 'Created by',
                    plural: 'Created by',
                    language: 'en',
                },
            ],
        }),
        primary_contact: ReferenceColumn({
            dependent: 'company',
            label: 'Primary contact',
            referenceTable: 'sys_user',
        }),
        sys_updated_by: StringColumn({
            label: [
                {
                    label: 'Updated by',
                    plural: 'Updated by',
                    language: 'en',
                },
            ],
        }),
        company: ReferenceColumn({
            label: 'Company',
            referenceTable: 'core_company',
            referenceQual: 'customer=true',
        }),
    },
})
